(function(){"use strict";const examMode=!!window.__mkExamMode;const pages=[{id:"home",title:"Find your route",kind:"page",priority:10,surface:"[data-wiki-home]",path:"(?:^|/)(?:index\\.html)?$",steps:[{title:"Begin with a task",text:"Choose Explore Year 1 for course notes, or Find a concept when you know the idea you need. The four cards below offer routes for orientation, understanding, revision and teaching.",target:".wh-actions",visual:"list",action:"Choose the route that fits today's question."},{title:"Check coverage",text:"Year 1 has the fullest concept coverage. Year 2 currently has course hubs and Year 3 has no course material yet; a course link does not promise complete notes.",target:".wh-coverage",visual:"progress"},{title:"Use the shorter routes",text:"The footer opens the site guide, rankings and contributors. Personal activities are optional and separate from course grades.",target:".wh-footer-links",visual:"list"}]},{id:"exam-home",title:"Navigate Exam Mode",kind:"page",priority:10,surface:".hero",path:"(?:^|/)(?:index\\.html)?$",when:()=>examMode,steps:[{title:"Open a course or Finder",text:"Choose Year 1 for course notes, or Concept Finder to search published concepts. The header search also accepts titles, aliases, course codes and lecture tags.",target:".hero-actions",visual:"search"},{title:"Use local study tools",text:"Course diagnostics, mastery ratings and learning maps use records in this browser. Self-test folds explanations for recall; the Exam guide explains the limits of these tools.",target:"article.md-content__inner",visual:"progress"},{title:"Know what is unavailable",text:"Accounts, cloud sync, comments, rankings, Store and AI checks are unavailable in this mirror. Follow About Exam Mode for the full list before planning a study workflow.",target:".hero-actions a[href*='about']",visual:"privacy"}]},{id:"header-search",title:"Search from any page",kind:"panel",priority:84,surface:".md-search",when:root=>root.matches(":focus-within")&&(!!root.querySelector(".md-search__input:focus")||!!root.querySelector("[data-wiki-guide-ui]")),steps:[{title:"Search a title or code",text:"Enter a concept name, alias, course code or lecture tag. Suggestions can open a concept directly; the full results page offers a wider list.",target:".md-search__input",visual:"search",example:"m1c-lecture02"},{title:"Open the right result",text:"Check the course and title before opening a suggestion. If the list is broad, move to Concept Finder to combine tokens and select a revision pool.",target:".md-search__output",visual:"list",action:"Choose a matching result or open Finder."}]},{id:"explore-menu",title:"Use the Explore menu",kind:"panel",priority:86,surface:"#mk-random-tabs-random-panel",when:root=>root.style.visibility==="visible",steps:[{title:"Choose a discovery route",text:examMode?"Concept Finder builds a focused pool. Random Concept looks for an unvisited published idea first, while Random Route starts a guided connection through available notes.":"Concept Finder builds a focused pool. Random Concept looks for an unvisited published idea first; Random Route starts a guided connection, and Random AI Quiz uses an available untested check.",target:".mk-rt-panel-item, a",visual:"search"},{title:"Keep the scope in view",text:"Random routes lead to available content, not a prescribed study order. Use your course hub or Finder when you need a particular lecture or prerequisite.",target:"#mk-random-tabs-random-panel",visual:"list"}]},{id:"year-menu",title:"Choose a study year",kind:"panel",priority:85,surface:"#mk-random-tabs-year-panel",when:root=>root.style.visibility==="visible",steps:[{title:"Open the year directory",text:"Choose your study year, then a course hub. Year 1 has the fullest notes; later years have varying coverage, so read the availability notice in each directory.",target:"#mk-random-tabs-year-panel a",visual:"list"}]},{id:"rankings-menu",title:"Choose a rankings board",kind:"panel",priority:87,surface:"#mk-random-tabs-trending-panel",when:root=>!examMode&&root.style.visibility==="visible",steps:[{title:"Choose a metric first",text:"Choose Most Viewed, Most Popular or Most Tested concepts, or open the available user, EOR Rating and Collection Value boards. Each page explains its period and eligibility.",target:".mk-rt-panel-item, a",visual:"progress"},{title:"Respect visibility choices",text:"A learner may be absent because they opted out. Rankings are public comparisons of selected activity, not course grades or a complete record of learning.",target:"#mk-random-tabs-trending-panel",visual:"privacy"}]},{id:"my-menu",title:"Find your personal tools",kind:"panel",priority:88,surface:"#mk-random-tabs-activity-panel",when:root=>!examMode&&root.style.visibility==="visible",steps:[{title:"Open account and messages",text:"Account contains profile, privacy, connections and sync. Notifications and My public profile have direct shortcuts in this menu.",target:".mk-rt-panel-item",visual:"profile"},{title:"Resume learning work",text:"Resume review returns to an unfinished Finder session; Study sets and Saved pages open lists you kept. These are distinct browser and account records.",target:"#mk-random-tabs-activity-panel",visual:"list"},{title:"Explore optional activities",text:"My collection, Arena and Store are separate from course grades. Open the relevant screen for its rules and controls before spending or entering an official event.",target:"#mk-random-tabs-activity-panel",visual:"shop"}]},{id:"sidebar-course-picker",title:"Switch courses in the sidebar",kind:"panel",priority:89,surface:"#current-course-bar[data-course-menu-open='1'] .ccb-menu:not([hidden])",steps:[{title:"Choose a course",text:"This menu lists available course hubs. The current course is marked; choose another to open its index, then use the sidebar links for lectures and concepts.",target:".ccb-menu-item",visual:"list"},{title:"Return without switching",text:"Press Escape or click outside to close the picker. The Course control shows your current scope and does not change the concept page by itself.",target:"#current-course-bar .ccb-course-trigger",visual:"search"}]},{id:"sidebar-sort",title:"Order sidebar topics",kind:"panel",priority:78,surface:"#mk-sidebar-sortdock",when:root=>root.matches(":focus-within"),steps:[{title:"Choose an ordering",text:"The Sort by button cycles the available order for this year or course scope. It changes sidebar presentation, not concept content or your learning record.",target:".msb-sortdock__btn",visual:"list"},{title:"Open a topic",text:"After sorting, use a course or lecture group to expand its concept links. The course picker above the sort control changes which course index is open.",target:".md-nav__list, #current-course-bar .ccb-course-trigger",visual:"search"}]},{id:"year-overview",title:"Browse a study year",kind:"page",priority:12,surface:".year-hero",path:"(?:^|/)Year-[123]/index\\.html$",steps:[{title:"Choose the block",text:"Courses are grouped by block. Open the course title for its hub, where available concepts and lecture or week links are organised.",target:".year-block",visual:"list",action:"Pick the course you are studying."},{title:"Use topic shortcuts",text:"A topic chip opens one concept page directly. Course and concept availability differ by year, so check the notice on the page before planning a full revision route.",target:".course-card--topics",visual:"search"}]},{id:"course-hub",title:"Work through a course",kind:"page",priority:20,surface:".course-home",path:"(?:^|/)Year-[123]/[^/]+/index\\.html$",steps:[{title:"Pick the way in",text:"The task cards lead to this course's search, lecture or week index, topic groups and, where available, teaching preparation. Start with the question you have now.",target:".ch-task-grid",visual:"list"},{title:"Search inside this course",text:"Enter a title or term and submit Search in course. Use the Finder link below when you want filters, multiple concepts or a saved set.",target:".course-search",visual:"search",example:"limit"},{title:"Return to your unit",text:"Choose a lecture or week tile to open its tagged concepts in Finder. These tags organise published pages; confirm the teaching schedule in your course materials.",target:".ch-unit-grid",visual:"list"},{title:"Open one concept",text:"Expand a topic group and follow a concept link. Course diagnostics, if shown beside the title, summarises your personal records rather than course grades.",target:".ch-concept-grid",visual:"progress"}]},{id:"course-library",title:"Browse this course library",kind:"page",priority:20,surface:".course-search[data-course-token]",path:"(?:^|/)Year-[123]/[^/]+/index\\.html$",when:()=>!document.querySelector(".course-home"),steps:[{title:"Search within this course",text:"Enter a topic and press Search in course. The results below the box are limited to this course; Finder can combine its code with other terms.",target:"#course-search-form",visual:"search",example:"simplex"},{title:"Browse a block or week",text:"The headings below group published concepts. Open a concept link directly, or choose an All Week link where offered to see the full tagged pool in Finder.",target:"article.md-content__inner h2, .course-block",visual:"list"},{title:"Check your own progress",text:"Course diagnostics beside the title opens visited, rated and lower-readiness topics when available. These are your study records rather than course grades.",target:"[data-course-mastery-map], .cmm-h1-entry",visual:"progress"}]},{id:"course-placeholder",title:"Read an unwritten course notice",kind:"page",priority:19,surface:"article.md-content__inner .admonition.info",path:"(?:^|/)Year-[123]/[^/]+/index\\.html$",steps:[{title:"Check availability",text:"This course has a hub or placeholder but no published concept notes here yet. Use your course learning environment for current materials; the notice does not promise a publication date.",target:".admonition.info",visual:"list"},{title:"Continue with available material",text:"Concept Finder searches what is actually published. Year 1 shows the courses with concept coverage if you want related foundations to review.",target:".admonition.info a",visual:"search"}]},{id:"year-three",title:"Year 3 availability",kind:"page",priority:12,surface:"article.md-content__inner",path:"(?:^|/)Year-3/index\\.html$",steps:[{title:"Use the current course materials",text:"Year 3 course pages are unavailable here. The course learning environment is the source for current teaching; use Finder or the other year directories for published Wiki concepts.",target:"article.md-content__inner",visual:"search"}]},{id:"concept-page",title:"Read and practise a concept",kind:"page",priority:18,surface:"article.md-content__inner",path:"(?:^|/)Year-[123]/[^/]+/(?!index\\.html)[^/]+\\.html$",steps:[{title:"Read the definition first",text:"Start with the definition, then compare the interpretation and example with your course notes. An unfamiliar symbol or assumption is a cue to open the linked prerequisite.",target:"h2.rf-h2, h2",visual:"practice"},{title:"Try recall before reopening",text:"Self-test folds explanatory sections so you can state the idea or work a short example first. Reveal the page again to check your reasoning.",target:".mw-title-menu, [data-rf-body], h2.rf-h2",visual:"practice",action:"Try explaining the concept in your own words."},{title:"Follow available connections",text:"Prerequisite links in the note lead to foundations. When the connections sidebar is enabled, it also shows dependents and related pages; these published links are not a complete curriculum map.",target:".lp-head, h2",visual:"map"},{title:"Record your own judgement",text:examMode?"Use the understanding bar to choose Unknown, Partial, Clear or Mastered. Reading alone does not assign a rating; Exam Mode keeps ratings in this browser.":"When mastery tools are enabled, use the understanding bar to choose Unknown, Partial, Clear or Mastered. Reading alone does not assign a rating; an AI check may suggest one, but you choose.",target:"#mw-mastery .mw-row [data-m], .mw-title-badge",visual:"progress",optional:true},{title:"Use page tools when available",text:examMode?"The understanding bar explains your rating and prerequisite readiness. Page actions can save a concept locally where shown; comments and edit requests are unavailable in Exam Mode.":"Page actions can save a concept for later; the understanding bar explains your rating and prerequisite readiness. On the full site, comments below the note invite questions and corrections.",target:".mk-fav-h1-btn, #mw-mastery",visual:"list",optional:true}]},{id:"page-actions",title:"Save or share this concept",kind:"panel",priority:91,surface:".mk-page-action-menu:not([hidden])",steps:[{title:"Choose a saved-page purpose",text:"Favourite, Study later and Review later are separate choices. A check mark shows which lists already contain this concept; select an active item again to remove it.",target:".mk-page-action-item[data-action]",visual:"list"},{title:"Use the other actions",text:examMode?"Use only the local page actions shown here. Account recommendations and edit requests are unavailable in Exam Mode.":"A connected account can recommend the page to a study connection. Edit page opens a suggestion workflow; submitting a suggestion is separate from changing the published note.",target:".mk-page-action-item",visual:"share"}]},{id:"mastery-title-menu",title:"Choose an understanding level",kind:"panel",priority:92,surface:".mw-title-menu",steps:[{title:"Rate current understanding",text:"Choose Mastered, Clear, Partial or Unknown after trying the concept. An unrated page is distinct from Unknown; your selection records a personal judgement, not a course mark.",target:".mw-title-menu-levels [data-m]",visual:"progress"},{title:"Inspect the evidence",text:examMode?"Prerequisite readiness uses recorded foundation ratings; Recap shows this concept's local study activity. Manage mastery opens your browser-local record. AI checks are unavailable in Exam Mode.":"Prerequisite readiness uses recorded foundation ratings; Recap shows this concept's recent study activity. Use the AI check to test recall, or Manage mastery for your full record.",target:".mw-title-menu-btn--ready, .mw-title-menu-btn--recap, .mw-title-menu-btn--manage",visual:"practice"},{title:"Control the bar",text:"Before rating this page, the eye control can hide or show the in-page mastery bar. After an explicit rating, the title badge remains the main shortcut.",target:".mw-title-menu-btn--toggle, .mw-title-badge",visual:"settings",optional:true}]},{id:"mastery-bar",title:"Use the understanding bar",kind:"panel",priority:79,surface:"#mw-mastery",when:root=>root.matches(":focus-within"),steps:[{title:"Understand the levels",text:"Open the information button for the four level meanings. Pick the level that matches what you can explain now; no rating and Unknown are different states.",target:".mw-level-info, .mw-row [data-m]",visual:"progress"},{title:"Check foundations and history",text:"Prereq summarises the ratings of linked foundations, while Recap lists visits, reviews and rating activity for this concept. Manage mastery opens the wider record.",target:"[data-mw-ready-trigger], [data-mw-recap-trigger], [data-mw-manage]",visual:"progress"},{title:"Keep the page readable",text:"Hide collapses the bar before a first rating. The title control can show it again; hiding the bar does not erase stored ratings or visits.",target:"[data-mw-hide]",visual:"settings"}]},{id:"mastery-level-info",title:"Interpret understanding levels",kind:"panel",priority:96,surface:"#mw-level-info-dialog[open]",steps:[{title:"Choose honestly",text:"Read the examples for Mastered, Clear, Partial and Unknown, then close this explanation to rate the concept. These labels are private learning notes, not course grades.",target:".mw-level-info-list, .mw-level-info-close",visual:"progress"}]},{id:"mastery-prerequisites",title:"Read prerequisite readiness",kind:"panel",priority:95,surface:"#mw-ready-popover:not([hidden])",steps:[{title:"Read the score as a signal",text:"Prerequisite readiness combines recorded foundation ratings, with direct links weighted more than distant ones. Not assessed means no explicit prerequisite rating yet; it is not evidence of zero understanding.",target:".mw-ready-score-card, .mw-ready-formula",visual:"progress"},{title:"Open a weak foundation",text:"The list separates direct and indirect prerequisites. Follow a concept link to test the missing step; the score itself does not change your rating on this page.",target:".mw-ready-list, .mw-ready-link",visual:"map"}]},{id:"mastery-recap",title:"Read your concept recap",kind:"panel",priority:95,surface:"#mw-recap-popover:not([hidden])",steps:[{title:"Review your own timeline",text:"Recap shows your current rating and recent visits, reviews and direct rating events where recorded. No recent activity is an empty history, not a judgement about mastery.",target:".mw-recap-rating, .mw-recap-list",visual:"progress"},{title:"Choose the next action",text:"Return to the note to test yourself, or open Manage mastery to filter the wider record. The recap reports activity; it does not award a grade.",target:"#mw-recap-popover",visual:"practice"}]},{id:"concept-comments",title:"Discuss a concept",kind:"panel",priority:77,surface:".mk-page-comments",when:root=>root.matches(":focus-within")||location.hash==="#comments",steps:[{title:"Write a focused question",text:"Use the composer to ask about this concept or suggest a correction. A name is optional for guests; a connected learner may choose anonymous posting before sending.",target:".mk-comment-composer textarea, .mk-comment-anon-row, .mk-comment-name-input",visual:"share"},{title:"Read and organise replies",text:"Sort comments by newest, oldest or most popular. Open replies beneath a comment; use Reply to continue that thread rather than starting an unrelated one.",target:".mk-comments-sort-trigger, .mk-comment-list, .mk-comment-replies-toggle",visual:"list"},{title:"Correct or flag a comment",text:"An owner can edit or delete their own comment. Report flags another comment for review; the visible status confirms whether your action was accepted.",target:".mk-comment-actions, .mk-comment-report-btn",visual:"privacy"}]},{id:"self-test",title:"Try the concept before revealing it",kind:"page",priority:80,surface:"article.md-content__inner",path:"(?:^|/)Year-[123]/[^/]+/(?!index\\.html)[^/]+\\.html$",when:root=>{if(!root.querySelector(".rf-body[hidden]"))return false;if(window.MkConceptFold?.isSelfTestEnabled?.())return true;try{return window.sessionStorage.getItem("random_review_mode_v1")==="1";}catch(_){return false;}},steps:[{title:"Try recall first",text:"The explanation is folded. State the definition or work an example before opening the next section; this reading mode does not record a score or mastery rating.",target:"h2.rf-h2 .rf-toggle",visual:"practice",action:"Answer in your own words before revealing."},{title:"Reveal and compare",text:"Open a heading to check the definition, intuition or example. If you missed a step, follow its prerequisite link and return to the same question.",target:"h2.rf-h2 .rf-toggle, .rf-body:not([hidden])",visual:"practice"},{title:"Record a separate judgement",text:examMode?"Choose a mastery level only after checking your understanding. This local rating stays in the current browser and does not change merely because you revealed the page.":"Choose a mastery level only after checking your understanding. A review session's Done & next records the session step separately.",target:".mw-title-badge, h1",visual:"progress"}]},{id:"finder",title:"Find and select concepts",kind:"page",priority:22,surface:".wiki-finder",path:"(?:^|/)find\\.html$",steps:[{title:"Start with a simple search",text:"Type a concept name or course code and press Search. A course code such as m1c narrows the pool; a lecture tag such as m1c-lecture02 narrows it further.",target:"#fb-simple-search, #search-form",visual:"search",example:"m1c-lecture02"},{title:"Build a precise query",text:"Open Advanced query to add tokens. Combine them with AND, OR and parentheses; the example button shows the board layout before you create your own expression.",target:"#fb-search-mode, #wf-query-editor",visual:"search",example:"m1c AND (derivative OR integral)"},{title:"Read the result cards",text:examMode?"A result opens its concept page. Select several published results for random revision; check each title and course before opening the pool.":"A result opens its concept page. Select several results when you want random revision or a named study set; check each title before saving the pool.",target:"#search-results",visual:"list"},{title:examMode?"Revise a selected pool":"Keep useful selections",text:examMode?"Use the selected concepts for random revision, or open a result directly. Saved study sets and AI-test are unavailable in Exam Mode.":"Open Study sets to save the selected concepts in order. Sets stay in this browser and need their own JSON backup for transfer.",target:examMode?"#cr-random, #search-results":"[data-study-sets-entry], #study-sets-workspace",visual:"list",action:examMode?"Select a few concepts, then start random revision.":"Select a few concepts, then open Study sets."}]},{id:"finder-query",title:"Build an advanced query",kind:"panel",priority:70,surface:"#wf-query-editor",when:()=>!!document.querySelector("#fb-search-mode[aria-expanded='true']"),steps:[{title:"Add a searchable term",text:"Type a title word, alias, course code or lecture tag, then choose a suggestion or press Enter. The token pool saves terms for reuse; it does not run a search yet.",target:"#search-input, .fb-tokensearch-dropdown",visual:"search",example:"m1c-lecture02"},{title:"Place terms on the board",text:"Choose a token in the pool to insert it at the highlighted slot. Select another insertion slot before adding the next term; the example button loads a working expression.",target:".fb-tokenbtn, .fb-slot, [data-fb-example]",visual:"list",example:"m1c AND limit"},{title:"Choose the logic",text:"AND requires both sides; OR accepts either. Use parentheses to group alternatives, such as one course AND two related topics. The board shows whether the expression is ready to run.",target:"#fb-and, #fb-or, #fb-lp, #fb-rp",visual:"search",example:"m1c AND (limit OR derivative)"},{title:"Edit without retyping",text:"Move a chip with its arrows or drag it, remove a chip with ×, and use Undo or Redo for board edits. Clear resets the expression; Clear tokens also removes saved pool terms.",target:".fb-chip__move, #fb-undo, #fb-redo, #fb-clear, #fb-clear-tokens",visual:"list"},{title:"Run and check the result",text:"Run search applies this board. Check Last search above the results: an edited draft does not replace results until you run it. If a typo correction appears, Edit as typed restores your term.",target:"#fb-run, [data-sr-applied-query], [data-fb-fuzzy-act='edit']",visual:"search"}]},{id:"finder-results",title:"Use search results",kind:"panel",priority:72,surface:"#search-results",when:root=>!!root.querySelector(".csr-wrap.is-visible .csr-result-summary"),steps:[{title:"Confirm the applied query",text:"Last search and the match count describe the current results. If the editor says Draft changed, run the new query before treating these cards as its answer.",target:".csr-result-summary",visual:"search"},{title:"Narrow and order the list",text:"Filters choose mastery states such as Unvisited or Unrated. Sort can show relevance, recent views, course order or title order. These controls change browsing, not the underlying search expression.",target:"[data-sr-toggle='filters'], #csr-filter-panel, .mk-sortbtn",visual:"search"},{title:"Select a revision pool",text:"Tick concept rows after checking title and course. All and None apply to every currently filtered result across pages, while pagination changes only which rows you see.",target:".csr-row input[data-loc], #cr-all, #cr-none, .csr-foot",visual:"list"},{title:"Choose the reading mode",text:examMode?"Open Revision for ordinary reading or folded Self-test. AI-test and Store unlocks are unavailable in Exam Mode.":"Open Revision for ordinary reading, folded Self-test or an AI-test question. Some modes require a Store unlock; AI checking also needs internet access.",target:"[data-sr-toggle='revision'], #csr-revision-panel",visual:"practice"},{title:"Use the selection",text:examMode?"Start random opens an eligible selected concept. Enrichment and retired concepts stay searchable but are excluded from random revision; check the selection explanation when shown.":"Start random opens an eligible selected concept. Save as set creates an ordered browser-local list. Enrichment and retired concepts stay searchable but are excluded from random revision; check the selection explanation when shown.",target:examMode?"#cr-random, [data-sr-selection-explanation]":"#cr-random, [data-study-set-create], [data-sr-selection-explanation]",visual:"list"}]},{id:"finder-empty-results",title:"Recover from an empty search",kind:"panel",priority:72,surface:"#search-results",when:root=>!!root.querySelector(".csr-result-summary + .sr-empty"),steps:[{title:"Check what was searched",text:"Read Last search before editing: an advanced draft does not change the applied query until Run search. Zero matches can also mean your course or lecture tag is too narrow.",target:".csr-result-summary, .sr-empty",visual:"search"},{title:"Broaden one condition",text:"Return to the query board, remove one AND condition or try a broader title word, then run again. A corrected spelling can be edited as typed when the suggestion is not what you intended.",target:"[data-wf-edit], #fb-search-mode, [data-fb-fuzzy-act='edit']",visual:"search"}]},{id:"study-sets",title:"Keep a study set",kind:"panel",priority:90,surface:"#study-sets-workspace:not([hidden])",steps:[{title:"Name and order the set",text:"Save selected Finder concepts under a name. Add a short preparation note, move items into the order you want, or remove an item before saving.",target:".wss-fields, .wss-items",visual:"list"},{title:"Keep a transfer copy",text:"Set backup (.json) preserves one set or draft; Library backup (.json) preserves all saved sets. Set notes (.md) is readable but cannot be imported as a backup.",target:"[data-wss-action='draft-json'], [data-wss-action='backup'], .wss-actions",visual:"privacy"},{title:"Review when ready",text:"Review this set starts a separate finite session. Saving alone does not start review, change mastery or earn extra XP.",target:"[data-wss-action='review'], .wss-editor",visual:"practice"}]},{id:"review-session",title:"Review one concept at a time",kind:"panel",priority:94,surface:"#study-session:not([hidden])",steps:[{title:"Choose a short queue",text:"Start a 5- or 10-concept review from a saved set. The queue follows your saved order and shows the actual number available.",target:".ss-plan, .ss-choices",visual:"practice"},{title:"Try, then record the step",text:"Open the concept, try Self-test or an available AI check, then choose Done & next or Skip & next. Done records this review step; it does not change mastery.",target:".ss-current, .ss-actions",visual:"progress"},{title:"Pause or finish",text:"Pause saves your place in this browser. Resume restores the queue and position, but not an unfinished AI question; the summary can be downloaded when the session ends.",target:".ss-more, .ss-footer",visual:"privacy"}]},{id:"mastery-manager",title:"Inspect your learning record",kind:"panel",priority:90,surface:"#mm-panel",steps:[{title:"Filter the record",text:"Choose a course, type a concept or lecture, or filter by mastery level. Visited, unrated and explicitly Unknown are different states.",target:"#mm-filter, #mm-course, #mm-level-filters",visual:"search"},{title:"Inspect the evidence",text:"Each card shows your current rating and offers visit history and, when available, AI check details. These are your study records, not course grades.",target:"#mm-list",visual:"progress"},{title:"Change with care",text:"Use the level selector on a card to revise a rating. Data actions can remove records, so check the scope before confirming a deletion.",target:".mm-level, .mm-data-actions",visual:"privacy"}]},{id:"ai-check",title:"Try an AI concept check",kind:"panel",priority:92,surface:"#aiq-panel",steps:[{title:"Choose the check",text:"Read each question and select an answer before revealing feedback. An internet connection is required to check answers; an account is optional for practice.",target:".aiq-question, .aiq-options, #aiq-panel",visual:"practice"},{title:"Use the explanation",text:"Compare the returned explanation with your reasoning and the course source. If checking fails, your choice remains in the open quiz for Retry check answer.",target:".aiq-feedback, #aiq-panel",visual:"practice"},{title:"Choose your mastery",text:"The result may suggest a level, but your rating remains your decision. The questions are repeatable learning practice, not a confidential exam bank.",target:".aiq-result-card, #aiq-panel",visual:"progress"}]},{id:"concept-connections",title:"Trace concept connections",kind:"panel",priority:75,surface:"#lp-side-panel",when:root=>root.contains(document.activeElement)||!!root.closest("#lp-mobile-sheet.lp-expanded"),steps:[{title:"Work backwards",text:"Prerequisites are the published concepts that this page links to as foundations. Open one when the current explanation assumes a step you cannot yet explain.",target:".lp-pres",visual:"map"},{title:"Look ahead",text:"Dependents show pages that use this idea; related concepts offer other nearby links. These links help exploration but are not an official teaching order.",target:".lp-deps, .lp-rel",visual:"map"},{title:"Open a map",text:"The map button opens visual views of the same published relationships. Knowledge masking can hide unfamiliar titles until you choose to reveal them.",target:"[data-lp-open-map], [data-lp-fog-switch]",visual:"map"}]},{id:"knowledge-gps",title:"Follow a guided study route",kind:"panel",priority:96,surface:"#lp-gps-modal.lp-open",steps:[{title:"Read the route",text:"Start and Target show the endpoints. The numbered cards explain which concepts to learn or review before the goal; the route uses published links and your current study record.",target:".lp-gps-stats, .lp-gps-route",visual:"map"},{title:"Begin or continue",text:"Start guided study opens the first concept. Continue takes you to the next step when available; returning to the current concept keeps the route context in this browser.",target:"[data-lp-gps-start], [data-lp-gps-next-index]",visual:"practice"},{title:"Try another valid route",text:"Another valid path proposes a different route through the same published graph. Compare its steps before starting; Close returns to the concept page.",target:"[data-lp-gps-reroll], .lp-gps-close",visual:"map"}]},{id:"course-diagnostics",title:"Choose a course review target",kind:"panel",priority:94,surface:"#mk-course-mastery-map-modal .cmm-modal__dialog",steps:[{title:"Read the course summary",text:"Visited and rated counts measure different things. Course mastery readiness summarises your current study record; choose its information button for the interpretation before comparing units.",target:".cmm-metrics, [data-cmm-course-readiness-info]",visual:"progress"},{title:"Scan the concept heatmap",text:"Each square is a concept and each row a lecture or week. Colour and the row percentage suggest where to review first; select a square to inspect its evidence.",target:".cmm-stage .cmm-heatmap, [data-cmm-select-concept]",visual:"map"},{title:"Use the side summaries",text:"The cards beside the heatmap show learning-unit status, recent change and the distribution of concept states. Their lecture links jump to the corresponding expandable list below.",target:".cmm-stage__side, [data-cmm-jump-lecture]",visual:"progress"},{title:"Inspect one concept",text:examMode?"The Current focus card separates mastery from prerequisite readiness and lists local visits. Open its title to read the concept; this browser's records are not course grades.":"The Current focus card separates mastery from prerequisite readiness and lists visits and AI checks. Open its title to read the concept; public averages, when present, describe participating records rather than a target grade.",target:".cmm-focuscard, .cmm-public-score-avgs",visual:"progress"},{title:"Filter the lecture list",text:"Toggle Low mastery readiness or Unvisited to narrow the expandable lists. Open a lecture or week to read its concept rows, then follow a concept link for definitions and examples.",target:"[data-cmm-filter], [data-cmm-lecture-toggle], .cmm-lecture__body",visual:"list"},{title:"Close and return",text:"Close the diagnostics dialog to return to the course hub. Your recorded visits and mastery ratings remain; this view does not assign course grades.",target:"[data-cmm-close]",visual:"progress"}]},{id:"map-nearby",title:"Explore the Nearby map",kind:"panel",priority:98,surface:"#lp-map-modal.lp-open",steps:[{title:"Start at this concept",text:"Nearby shows the current concept and its published neighbours. Map tips explain the controls; the tabs lead to Prerequisites and Dependents views of recorded links.",target:"[data-lp-map-tip-toggle], .lp-map-tabs",visual:"map"},{title:"Preview a neighbour",text:"On a PC, hover or click a side node to preview its connections and open its two-action dock. A click retains a temporary preview; it has not expanded your map session yet.",target:".lp-mapstage a.lp-node, #lp-nearby-node-actions",visual:"map",action:"Choose a side node, then inspect its actions."},{title:"Expand or open",text:"Expand map adds that node's neighbourhood to this map session. Open page navigates to its concept note. Expanded appears when that node adds nothing new.",target:"[data-lp-node-expand], [data-lp-node-open]",visual:"map"},{title:"Pan and zoom",text:"Drag the map background to pan. Use minus, plus, the slider or Reset to change zoom; on touch devices, pinch on the map. Fullscreen gives the graph more room.",target:".lp-mapstage, [data-zoom-range], [data-zoom-reset], [data-lp-fullscreen]",visual:"map"},{title:"Choose masking",text:"Masking hides unfamiliar titles without removing their connections. Select a masked node to reveal it; the switch changes this visibility choice, not your mastery rating or the graph links.",target:"[data-lp-fog-switch]",visual:"privacy"},{title:"Discover optional chests",text:"A signed-in account may receive a server-decided treasure after expanding new nodes. If a chest appears, open it to see its receipt; availability and daily limits depend on the account and server.",target:".lp-map-chests, .lp-map-chest",visual:"shop",optional:true},{title:"Close to reset exploration",text:"Close dismisses the map and discards this session's added nodes and preview. Reopening starts from the original Nearby neighbourhood; your underlying study record remains separate.",target:".lp-close",visual:"map"}]},{id:"map-chest-reward",title:"Claim a map discovery",kind:"panel",priority:101,surface:".lp-map-chest-dialog[open]",steps:[{title:"Read the receipt",text:"This receipt follows a server-confirmed chest opening. Read the reward and choose Keep exploring to return to the map. A failed claim offers Retry for the same chest instead of a second award.",target:".lp-chest-reward-card, .lp-map-chest-dismiss",visual:"shop"}]},{id:"map-prerequisites",title:"Trace prerequisites",kind:"panel",priority:99,surface:"#lp-h1sg-modal.lp-open[data-lp-mode='toHere']",steps:[{title:"Read the direction",text:"Prerequisites traces published foundations towards this concept. Open Map tips for route controls, then use the filter to locate a foundation in the displayed graph.",target:"[data-lp-map-tip-toggle], [data-lp-h1sg-filter-input]",visual:"map"},{title:"Choose a learning path",text:"Select a route node to highlight a path from Start to Goal. The map reports how many concepts the path contains; this traces recorded links, not every mathematical prerequisite.",target:".lp-mapstage .lp-node, [data-lp-map-route-endpoints]",visual:"map"},{title:"Begin guided study",text:"After selecting a path, choose Start guided study when it appears. It follows the selected concepts in order; you can return to the map to choose another path.",target:"[data-lp-h1sg-dock-launch]",visual:"practice",optional:true},{title:"Adjust the view",text:"Drag the background to pan; use the slider, plus or minus to zoom and Reset to restore scale. Masking changes which unfamiliar titles are visible without changing links.",target:"[data-lp-h1sg-zoom-range], [data-lp-h1sg-zoom-reset], [data-lp-fog-switch]",visual:"map"},{title:"Switch or close",text:"Use the tabs for Nearby or Dependents. Close returns to the concept page; the map is an exploration aid rather than an official teaching order.",target:"[data-lp-map-tab='fromHere'], [data-lp-map-tab='local'], .lp-close",visual:"map"}]},{id:"map-dependents",title:"Trace later uses",kind:"panel",priority:99,surface:"#lp-h1sg-modal.lp-open[data-lp-mode='fromHere']",steps:[{title:"Read the direction",text:"Dependents traces published pages that later use this concept. Open Map tips if needed and filter the graph to locate a particular later topic.",target:"[data-lp-map-tip-toggle], [data-lp-h1sg-filter-input]",visual:"map"},{title:"Choose a learning path",text:"Select a later concept to highlight a path from Start to Goal. An absent link means only that the published graph does not record it.",target:".lp-mapstage .lp-node, [data-lp-map-route-endpoints]",visual:"map"},{title:"Begin guided study",text:"After selecting a path, use Start guided study when it appears to follow its concepts in order. Return to the map to choose another target.",target:"[data-lp-h1sg-dock-launch]",visual:"practice",optional:true},{title:"Adjust visibility and scale",text:"Pan by dragging the background. Zoom with the slider or buttons and use Reset to recenter the view. Masking hides unfamiliar labels without deleting connections.",target:"[data-lp-h1sg-zoom-range], [data-lp-h1sg-zoom-reset], [data-lp-fog-switch]",visual:"map"},{title:"Return to foundations",text:"Switch to Prerequisites or Nearby when the later page assumes a missing step. Close when ready to return to the current concept.",target:"[data-lp-map-tab='toHere'], [data-lp-map-tab='local'], .lp-close",visual:"map"}]},{id:"random-entry",title:"Start random exploration",kind:"page",priority:22,surface:"#random-entry-message",path:"(?:^|/)random\\.html$",steps:[{title:"Follow the redirect",text:"This page sends you to a random published concept. If loading fails, choose Retry or return to Concept Finder to define a smaller pool.",target:"#random-entry-message, #random-entry-retry",visual:"search"}]},{id:"custom-random-redirect",title:"Find a focused revision pool",kind:"page",priority:22,surface:"#concept-finder-redirect",path:"(?:^|/)custom-random\\.html$",steps:[{title:"Continue in Finder",text:"Custom Random moved into Concept Finder. The link keeps a bookmarked query when possible; select a pool there before starting random revision.",target:"#concept-finder-redirect",visual:"search"}]},{id:"rankings",title:"Read rankings and honours",kind:"page",priority:24,surface:".wiki-rankings",path:"(?:^|/)trending\\.html$",steps:[{title:"Choose the board",text:"Open a learner or concept board and read its metric label before comparing rows. Activity, EOR Rating and Collection Value measure different things.",target:"#trending-app .trending-block, #trending-app",visual:"progress"},{title:"Choose the period",text:"Use period tabs to switch between current standings, recent changes and monthly honours where offered. Honours are awarded only after a UTC calendar month closes and results are finalised.",target:".trending-tabs, #trending-app",visual:"list"},{title:"Interpret the limits",text:"Public boards omit people who have opted out; missing historical Collection Value is not treated as zero. Rankings can encourage practice but do not diagnose what you should study next.",target:".trending-block, details",visual:"privacy"}]},{id:"teaching-workbench",title:"Prepare a teaching review",kind:"page",priority:25,surface:"[data-teaching-workbench]",path:"(?:^|/)teaching\\.html$",steps:[{title:"Set the scope",text:"Choose a course and either one concept or a whole lecture or week. Then choose relationship depth and list order; begin with a small neighbourhood.",target:"[data-tw-form]",visual:"map"},{title:"Add your purpose",text:"The optional learning outcome and notes help turn the graph into a lesson plan. The text stays on this page unless you download or print the review.",target:"[data-tw-notes-editor]",visual:"practice"},{title:"Build and verify",text:"Build the relationship review, follow concept links and check sources against your course materials. A missing graph link does not prove that no prerequisite exists.",target:"[data-tw-build], [data-tw-review]",visual:"list"},{title:"Take the result away",text:"Download Markdown or print the review if you need to keep it. Account backup does not include teaching notes from this page.",target:"[data-tw-download], [data-tw-print]",visual:"share"}]},{id:"arena",title:"Choose an Arena activity",kind:"panel",priority:95,surface:".ar-dialog[open]",steps:[{title:"Choose the activity",text:"Duels are live, Ghost races let people play at different times, and Weekend events follow the displayed course scope. Your record shows completed results.",target:".ar-nav",visual:"practice"},{title:"Read the current rules",text:"Open the rules in the selected section before an official run. Practice, skipped questions and unfinished matches can have different scoring and reward outcomes.",target:".ar-rules, .ar-content",visual:"list"},{title:"Check connection and status",text:"An account connection is required for official play. The status area reports loading or connection trouble; do not assume an unanswered invitation or unavailable weekend is an active match.",target:".ar-status, .ar-connection",visual:"progress"}]},{id:"arena-duels",title:"Manage duel challenges",kind:"panel",priority:97,surface:".ar-dialog[open] .ar-hero:not(.ar-hero--events)",steps:[{title:"Check your invitations",text:"Your challenges separates live duels from Ghost races. Open a card to read its course, question count, time and current status before accepting or replying.",target:"[data-challenges], [data-ghosts]",visual:"list"},{title:"Invite from a profile",text:"Open another learner's public profile to challenge them. Live duels require both players online; Ghost races let each person complete the same questions at different times.",target:".ar-content .ar-empty, .ar-rules",visual:"profile"},{title:"Read the terms",text:"How a duel works and How a ghost race works contain scoring, exit and reward rules. Check these before agreeing to a stake or starting a timed run.",target:".ar-rules",visual:"practice"}]},{id:"arena-offer",title:"Set challenge terms",kind:"panel",priority:99,surface:".ar-dialog[open] .ar-form",when:root=>!!root.querySelector("[data-ar='send-offer']"),steps:[{title:"Choose the format and course",text:"Live duel means playing together; Ghost race means separate runs. Choose a course with enough available questions, then set the supported question count.",target:"[name='format'], [name='course'], [name='count'], [name='ghostCount']",visual:"practice"},{title:"Set timing and stake",text:"For a live duel, start when both are ready or choose a local scheduled time. Read any stake and account balance before sending; the server confirms the proposal.",target:"[name='when'], [name='start'], .ar-form [data-offer-note]",visual:"settings"},{title:"Send and watch status",text:"Send invitation, then return to Your challenges to see acceptance, counteroffers or expiry. Nothing is played merely by sending a Ghost race invitation.",target:"[data-ar='send-offer'], [data-ar='back']",visual:"share"}]},{id:"arena-challenge",title:"Review a duel invitation",kind:"panel",priority:98,surface:".ar-dialog[open] .ar-terms",steps:[{title:"Inspect the proposal",text:"Check opponent, course, question count, scheduled time, proposal revision and expiry. Any stake is shown separately before you decide.",target:".ar-terms, .ar-wager",visual:"list"},{title:"Choose a response",text:"Accept, suggest different terms, decline or cancel according to your role and the invitation state. The rules disclosure explains when a duel becomes rated and what happens if it is left.",target:".ar-actions, .ar-rules",visual:"practice"}]},{id:"arena-live-match",title:"Play a live duel",kind:"panel",priority:100,surface:".ar-dialog[open] .ar-scoreboard",steps:[{title:"Join the table",text:"Check both players and their scores. Choose I'm ready when the agreed time arrives; both players must be online and ready before the first question begins.",target:".ar-scoreboard, [data-ar='ready']",visual:"progress"},{title:"Answer each round",text:"Select an option when the question appears. A wrong choice brings a pause and is crossed out; the first correct answer earns that round's point.",target:".ar-round .ar-options, .ar-round .ar-note",visual:"practice"},{title:"Review and advance",text:"Read the explanation, then choose Next question. Both players must advance. Leaving a started match can affect its result, so read the confirmation before using Leave match.",target:".ar-explanation, [data-ar='next'], [data-ar='leave']",visual:"practice"}]},{id:"arena-ghost-race",title:"Play a Ghost race",kind:"panel",priority:99,surface:".ar-dialog[open] .ar-content",when:root=>/Ghost race/.test(root.querySelector(".ar-section-head .ar-eyebrow")?.textContent||""),steps:[{title:"Check the race status",text:"The card shows the opponent, course, question count and invitation or play deadline. Accept or start only when you have time for a run; the clock begins when each question appears.",target:".ar-section-head, .ar-ready",visual:"progress"},{title:"Answer and compare",text:"Choose an answer on each question, read the explanation, then continue. The second player races the first player's recorded times; wrong answers pause or end that question.",target:".ar-ghost-round, [data-ar='ghost-next']",visual:"practice"},{title:"Finish or step away",text:"A started run can be reopened from Duels. Leaving or letting it stall may affect the result; the race card and confirmation explain the current consequence.",target:"[data-ar='ghost-leave'], [data-ar='back'], .ar-ghost-rounds",visual:"privacy"}]},{id:"arena-record",title:"Read your competition record",kind:"panel",priority:98,surface:".ar-dialog[open] .ar-settings",steps:[{title:"Interpret the record",text:"The record separates rating, wins, draws, losses, honours and recent activities. A provisional rating or unfinished event should not be read as a final award.",target:".ar-record-stats, .ar-honors, .ar-history",visual:"progress"},{title:"Choose visibility",text:"Allow invitations and Show my competition record on my public profile are separate choices. Change either checkbox, then Save preferences to send the update to your account.",target:".ar-settings [data-setting], [data-ar='save-settings']",visual:"privacy"}]},{id:"arena-weekend",title:"Play a weekend quiz",kind:"panel",priority:97,surface:".ar-dialog[open] .ar-hero--events",steps:[{title:"Check the weekend card",text:"The calendar shows the included courses, lecture or week scope and availability. A No competition scheduled card explains a gap and cannot start an official run.",target:".ar-events",visual:"list"},{title:"Open one question at a time",text:"A Quiz Sprint shows ten questions. The timer starts when each opens; incorrect answers pause the run, and skipping earns zero for that question.",target:".ar-content",visual:"practice"},{title:"Review after playing",text:"The board is provisional until the weekend closes and results settle. Answered questions can then be reviewed; eligibility for monthly honours follows the displayed rules.",target:".ar-rules, .ar-content",visual:"progress"}]},{id:"arena-event-detail",title:"Review a weekend event",kind:"panel",priority:98,surface:".ar-dialog[open] .ar-puzzle-list",steps:[{title:"Check the event scope",text:"Read the dates, timezone and included course topics. A closed event permits practice but cannot add another official score; an unavailable card explains why no run starts.",target:".ar-section-head, .ar-rules[aria-label]",visual:"list"},{title:"Start or resume one run",text:"When the event is active, Start my official run opens its scored sequence. Each question or puzzle card shows whether it is open, completed or available for practice.",target:"[data-ar='start-event'], .ar-puzzle-list",visual:"practice"},{title:"Read results carefully",text:"The event board can be provisional until finalisation. A calendar export downloads an .ics file; reminder controls affect website prompts, not a calendar you already imported.",target:".ar-leaders, [data-ar='calendar'], [data-ar='mute']",visual:"progress"}]},{id:"arena-sprint-question",title:"Answer a Sprint question",kind:"panel",priority:100,surface:".ar-dialog[open] .ar-content",when:root=>!!root.querySelector("[data-sprint-choice]"),steps:[{title:"Watch the question clock",text:"The clock starts when this question appears. Read the prompt and choose one option; official scoring rewards early correct answers, while practice cannot change your score.",target:".ar-question, [data-puzzle-clock], [data-sprint-choice]",visual:"practice"},{title:"Use feedback before continuing",text:"A wrong answer may pause choices before another try. Read the explanation after the question resolves; Skip ends an official question for zero points and asks for confirmation.",target:".ar-puzzle-feedback, [data-ar='skip-puzzle'], .ar-puzzle-continue",visual:"practice"}]},{id:"exam-about",title:"Use the Exam Mode guide",kind:"page",priority:11,surface:"article.md-content__inner",path:"(?:^|/)about\\.html$",when:()=>examMode,steps:[{title:"Find published notes",text:"Start with the Course Material and Search sections. Finder combines names, course codes and lecture tags, while each course hub offers a narrower search.",target:"#course-material, #search-and-concept-finder",visual:"search"},{title:"Interpret local records",text:"Local Mastery explains the four rating levels and how Course diagnostics uses them. An unrated page differs from Unknown; these records stay in this browser.",target:"#local-mastery, #course-diagnostics",visual:"progress"},{title:"Use only available revision",text:"Concept maps, Learning Path, random revision and Self-test remain available. Read Unavailable Features before relying on an account, AI check, saved set or online activity.",target:"#revision-modes, #unavailable-features",visual:"privacy"}]},{id:"about",title:"Use this site guide",kind:"page",priority:11,surface:".wiki-about",path:"(?:^|/)about\\.html$",when:()=>!examMode,steps:[{title:"Choose a task",text:"The short cards point to finding a concept, revising a small set, preparing to teach and optional activities. Start with the action that brought you here.",target:".wa-task-grid",visual:"list"},{title:"Keep the limits in view",text:"The Wiki supports course study. Your lecturer's syllabus and assessment guidance remain authoritative, and coverage varies by year and course.",target:".wh-hero-note, .wa-note",visual:"privacy"},{title:"Open precise rules when needed",text:"The detailed reference keeps the definitions of ratings, backup boundaries, privacy, rewards and competition rules. Its links preserve the older guide topics.",target:".wa-reference-links, .wa-jump",visual:"list"}]},{id:"about-reference",title:"Use the detailed feature reference",kind:"page",priority:10,surface:".wiki-about",path:"(?:^|/)about-reference\\.html$",steps:[{title:"Jump to the exact rule",text:"This reference keeps detailed explanations of ratings, backup boundaries, privacy, competition rules and course codes. Use the section links to find the topic you need.",target:".wa-jump",visual:"list"},{title:"Return to a shorter route",text:"The short site guide links to the main study tasks. Return there when you are ready to act, or use a feature's own replayable guide beside its controls.",target:".wiki-about > p:first-child",visual:"search"}]},{id:"contributors",title:"Meet the contributors",kind:"page",priority:12,surface:"article.md-content__inner",path:"(?:^|/)contributors\\.html$",steps:[{title:"Read the roles",text:"This page credits the people and sources behind the Wiki. Use the correction contact for a broken link, unclear step or source issue, with the page URL and a concise description.",target:"h1, .wiki-contributors",visual:"share"}]}];window.MkGuidePages=(window.MkGuidePages||[]).concat(pages);})();